s=[]
s.append(slide('slide-01-awareness-to-safe-action',p('Awareness turns recognition into a safer action.','Awareness เปลี่ยนการสังเกตเป็นการปฏิบัติที่ปลอดภัย'),p('Know the threat, your responsibility and the approved way to respond.','เข้าใจภัย หน้าที่ของตน และวิธีตอบสนองที่องค์กรกำหนด'),[
[p('Common cybersecurity threats','ภัยคุกคามไซเบอร์ทั่วไป'),p('Recognize an unusual request','สังเกตคำขอที่ผิดปกติ'),p('Understand common threats without assuming every unusual request is malicious.','เข้าใจภัยทั่วไป โดยไม่เหมารวมว่าทุกคำขอแปลกเป็นการโจมตี')],
[p('Their security responsibilities','หน้าที่ด้าน Security ของตน'),p('Know when to stop and ask','รู้ว่าเมื่อใดควรหยุดและถาม'),p('Employees act within their role and escalate concerns to responsible teams.','พนักงานปฏิบัติในหน้าที่และส่งข้อกังวลให้ทีมที่รับผิดชอบ')],
[p('Organizational security policies','นโยบาย Security ขององค์กร'),p('Use the approved process','ใช้ขั้นตอนที่อนุมัติไว้'),p('Policy and procedure make safe actions clear before a stressful incident.','นโยบายกับขั้นตอนช่วยให้รู้วิธีที่ปลอดภัยก่อนเกิดเหตุเร่งด่วน')],
[p('How to protect information and systems','วิธีปกป้องข้อมูลและระบบ'),p('Handle sensitive information safely','จัดการข้อมูลอ่อนไหวอย่างปลอดภัย'),p('Use authorized systems and access, rather than improvising public sharing.','ใช้ระบบและสิทธิ์ที่อนุมัติ แทนการแชร์สาธารณะตามสะดวก')],
[p('How to recognize and report suspicious activity','วิธีสังเกตและรายงานกิจกรรมที่น่าสงสัย'),p('Report using a known channel','รายงานผ่านช่องทางที่รู้จัก'),p('A prompt report lets the designated team assess and respond.','รายงานเร็วช่วยให้ทีมที่กำหนดประเมินและตอบสนองได้')]],
p('Security Awareness means understanding cybersecurity risks, threats, policies and appropriate behaviour. The source links this knowledge to five practical purposes: common threats, individual responsibilities, organizational policies, protection of information/systems, and recognition/reporting of suspicious activity. For example, an employee notices an unexpected request for customer records, checks the approved handling rule and reports it through a known channel. Awareness supports safe decisions; it is not a promise that people or technical controls will prevent every incident. The organization must make policies and reporting routes understandable and usable.','Security Awareness คือความเข้าใจความเสี่ยง ภัยคุกคาม นโยบาย และพฤติกรรมที่เหมาะสม ต้นฉบับเชื่อมความรู้นี้กับห้าเรื่อง ได้แก่ ภัยทั่วไป หน้าที่ของตน นโยบายองค์กร การปกป้องข้อมูล/ระบบ และการสังเกตพร้อมรายงานสิ่งผิดปกติ เช่น พนักงานเห็นคำขอข้อมูลลูกค้าที่ไม่คาดหมาย จึงตรวจแนวทางจัดการข้อมูลและรายงานผ่านช่องทางที่รู้จัก Awareness ช่วยตัดสินใจอย่างปลอดภัย แต่ไม่รับประกันว่าคนหรือเครื่องมือจะป้องกันได้ทุกเหตุ องค์กรต้องทำให้นโยบายและช่องทางรายงานเข้าใจง่ายและใช้ได้จริง'),
[p('Recognize risk without personally investigating an attacker.','สังเกตความเสี่ยงโดยไม่ต้องสืบสวนผู้โจมตีเอง'),p('Ask the responsible team when a request is unclear.','ถามทีมที่รับผิดชอบเมื่อคำขอไม่ชัดเจน'),p('A known reporting channel should be available before an incident.','ควรรู้ช่องทางรายงานก่อนเกิดเหตุ')],p('Recognition matters when people can act on it.','การสังเกตมีคุณค่าเมื่อคนลงมืออย่างเหมาะสมได้')))
s.append(slide('slide-02-awareness-and-training',p('Recognizing a risk and practising a task support each other.','การรู้ทันความเสี่ยงกับการฝึกลงมือช่วยเสริมกัน'),p('Awareness keeps a risk visible; training develops the knowledge and skills for the task.','Awareness ช่วยให้ใส่ใจความเสี่ยง ส่วน Training พัฒนาความรู้และทักษะสำหรับงาน'),[
[p('Awareness','Awareness'),p('Recognize a suspicious request','รู้จักคำขอที่น่าสงสัย'),p('Ongoing messages explain why the risk matters and where to get help.','สื่อสารต่อเนื่องให้รู้ว่าความเสี่ยงสำคัญอย่างไรและขอความช่วยเหลือที่ใด')],
[p('Training / practice','Training / การฝึก'),p('Practise the approved reporting process','ฝึกใช้ขั้นตอนรายงานขององค์กร'),p('Role-appropriate exercises build the ability to apply instructions.','แบบฝึกตามบทบาทช่วยให้ทำตามขั้นตอนได้จริง')]],
p('Awareness and training overlap, but serve useful teaching distinctions. A timely reminder can help a person recognize a suspicious message; practical training can teach how to use the reporting mechanism and what to do if they already clicked. NIST SP 800-50r1 supports ongoing awareness and learning appropriate to job responsibilities. Neither an annual attendance record nor a quiz result proves that safe behaviour is consistently supported at work. Use understandable reminders, relevant practice and feedback together. Do not treat awareness as only a one-time event or training as a replacement for working safeguards.','Awareness กับ Training มีส่วนทับซ้อนกัน แต่แยกจุดเน้นเพื่อเรียนรู้ได้ ข้อเตือนที่ทันเหตุการณ์ช่วยให้คนรู้จักข้อความน่าสงสัย ส่วนการฝึกช่วยให้ใช้ช่องทางรายงานเป็นและรู้ว่าควรทำอย่างไรหากคลิกไปแล้ว NIST SP 800-50r1 สนับสนุน Awareness ต่อเนื่องและการเรียนรู้ตามหน้าที่ หลักฐานเข้าเรียนประจำปีหรือคะแนน Quiz อย่างเดียวไม่พิสูจน์ว่าสถานที่ทำงานสนับสนุนพฤติกรรมปลอดภัยสม่ำเสมอ ควรใช้ข้อความที่เข้าใจง่าย การฝึกที่เกี่ยวกับงาน และ Feedback ร่วมกัน ไม่มองว่า Awareness จบในครั้งเดียว หรือใช้ Training แทนมาตรการป้องกันที่ทำงานได้'),
[p('A reminder explains a risk and the expected safe response.','ข้อความเตือนอธิบายความเสี่ยงและวิธีตอบสนอง'),p('Practice checks whether the person can carry out the response.','การฝึกตรวจว่าคนนำวิธีตอบสนองไปทำได้จริง'),p('Refresh learning when tools, duties or threats change.','ทบทวนการเรียนรู้เมื่อเครื่องมือ หน้าที่ หรือภัยเปลี่ยน')],p('Use knowledge, practice and support together.','ใช้ความรู้ การฝึก และการสนับสนุนร่วมกัน')))
behaviours=[('Take security seriously','เห็นความสำคัญของ Security','Pause before an unusual request','หยุดคิดเมื่อพบคำขอผิดปกติ'),('Follow security policies','ทำตามนโยบาย Security','Use approved handling rules','ใช้แนวทางจัดการข้อมูลที่กำหนด'),('Report suspicious activity','รายงานกิจกรรมน่าสงสัย','Use the known reporting channel','ใช้ช่องทางรายงานที่รู้จัก'),('Protect sensitive information','ปกป้องข้อมูลอ่อนไหว','Share only as authorized','แชร์ตามที่ได้รับอนุญาต'),('Ask questions when unsure','ถามเมื่อไม่แน่ใจ','Seek help before bypassing a control','ขอความช่วยเหลือก่อนข้ามมาตรการ'),('Accept security as a daily responsibility','รับผิดชอบ Security ในงานประจำวัน','Make safe behaviour normal work','ทำให้พฤติกรรมปลอดภัยเป็นงานปกติ')]
s.append(slide('slide-03-shared-daily-culture',p('Culture is what the team makes normal.','Culture คือสิ่งที่ทีมทำเป็นเรื่องปกติ'),p('Security is a shared daily responsibility, supported by clear expectations and usable processes.','Security เป็นความรับผิดชอบร่วมในงานประจำวัน โดยมีความคาดหวังชัดเจนและขั้นตอนที่ใช้ได้'),[[p(a,b),p(c,d),p('A behaviour encouraged by the original security-culture source.','พฤติกรรมที่ต้นฉบับสนับสนุนใน Security Culture')]for a,b,c,d in behaviours],
p('Security Culture is an organizational environment in which security is a shared responsibility. Awareness helps someone understand a suspicious-message risk; culture includes the expectations, support and repeated behaviour around that decision. In the source example, an employee reports a suspicious email instead of following its link. Other encouraged behaviours are following policies, protecting sensitive information, asking questions when unsure, taking security seriously and accepting it as daily work. Culture is broader than one person passing a quiz: colleagues and leaders must make secure actions practical, expected and supported.','Security Culture คือสภาพแวดล้อมองค์กรที่มอง Security เป็นความรับผิดชอบร่วม Awareness ช่วยให้คนเข้าใจความเสี่ยงของข้อความน่าสงสัย ส่วน Culture รวมความคาดหวัง การสนับสนุน และพฤติกรรมที่ทำซ้ำรอบการตัดสินใจนั้น ตัวอย่างต้นฉบับคือพนักงานรายงานอีเมลแทนการกดลิงก์ พฤติกรรมอื่นได้แก่ ทำตามนโยบาย ปกป้องข้อมูลอ่อนไหว ถามเมื่อไม่แน่ใจ เห็นความสำคัญของ Security และรับเป็นงานประจำ Culture จึงกว้างกว่าการสอบ Quiz ผ่านคนเดียว เพื่อนร่วมงานและผู้นำต้องทำให้การกระทำที่ปลอดภัยใช้ได้จริง เป็นสิ่งที่คาดหวัง และได้รับการสนับสนุน'),
[p('Knowing the rule supports awareness; routinely following it is evidence of behaviour.','รู้กฎสนับสนุน Awareness ส่วนทำตามสม่ำเสมอเป็นหลักฐานพฤติกรรม'),p('People need a practical way to ask and report.','คนต้องมีวิธีถามและรายงานที่ใช้ได้จริง'),p('Security teams have specialist duties; shared responsibility does not mean identical roles.','ทีม Security มีหน้าที่เฉพาะ ความรับผิดชอบร่วมไม่ได้แปลว่าทุกคนมีบทบาทเหมือนกัน')],p('Make the safe action the normal, supported action.','ทำให้วิธีที่ปลอดภัยเป็นเรื่องปกติที่ได้รับการสนับสนุน')))
duties=[('Demonstrate commitment to security','แสดงความจริงจังด้าน Security','Make security a visible priority','แสดงให้เห็นว่า Security สำคัญ'),('Provide appropriate resources','จัดสรรทรัพยากรที่เหมาะสม','Fund tools, staff and learning time','ให้เครื่องมือ คน และเวลาเรียนรู้'),('Support security awareness programs','สนับสนุนโครงการ Awareness','Sustain relevant learning','สนับสนุนการเรียนรู้ที่เกี่ยวข้องต่อเนื่อง'),('Encourage employees to report incidents','ส่งเสริมให้พนักงานรายงานเหตุ','Make help and reporting accessible','ให้ขอความช่วยเหลือและรายงานได้ง่าย'),('Lead by example','ทำให้ดูเป็นตัวอย่าง','Use MFA and follow the same policies','ใช้ MFA และทำตามนโยบายด้วย'),('Ensure security responsibilities are understood','ให้ทุกคนเข้าใจหน้าที่ด้าน Security','Explain roles and escalation routes','อธิบายบทบาทและช่องทางส่งต่อ')]
s.append(slide('slide-04-leadership-makes-rules-credible',p('Leaders make secure behaviour credible and possible.','ผู้นำทำให้พฤติกรรมปลอดภัยน่าเชื่อและทำได้จริง'),p('People notice both the policy and what management actually does.','คนเห็นทั้งนโยบายและสิ่งที่ผู้บริหารทำจริง'),[[p(a,b),p(c,d),p('Leadership enables shared responsibility without transferring all duties to employees.','ผู้นำสนับสนุนความรับผิดชอบร่วม ไม่โยนทุกหน้าที่ให้พนักงาน')]for a,b,c,d in duties],
p('Security leadership helps establish a strong culture through commitment, appropriate resources, support for awareness programs, encouragement to report incidents, leading by example and understood responsibilities. The original example is management following policy and using MFA themselves. An executive who bypasses the process sends a conflicting signal even when the written rule is clear. Leaders also need to give employees usable tools, time and clear escalation contacts. Accountability means assigning responsibilities and following up on improvements; it should not discourage prompt reporting of honest mistakes or replace investigation with blame.','Security Leadership สร้าง Culture ผ่านความจริงจัง ทรัพยากรที่เหมาะสม การสนับสนุน Awareness การส่งเสริมรายงานเหตุ การเป็นแบบอย่าง และทำให้เข้าใจหน้าที่ ตัวอย่างต้นฉบับคือผู้บริหารทำตามนโยบายและใช้ MFA ด้วยตนเอง หากผู้บริหารข้ามขั้นตอนย่อมส่งสัญญาณขัดกันแม้กฎเขียนไว้ชัด ผู้นำยังต้องให้เครื่องมือ เวลา และผู้ติดต่อส่งต่อปัญหาที่ใช้ได้จริง Accountability หมายถึงระบุผู้รับผิดชอบและติดตามการปรับปรุง ไม่ควรทำให้คนลังเลรายงานความผิดพลาดโดยสุจริต หรือใช้การกล่าวโทษแทนการตรวจสอบเหตุ'),
[p('Management follows the controls it asks staff to use.','ผู้บริหารใช้มาตรการเดียวกับที่ขอให้ทีมใช้'),p('Resources include usable reporting tools and time to learn.','ทรัพยากรรวมเครื่องมือรายงานที่ใช้ได้และเวลาเรียนรู้'),p('Clear roles and follow-up support accountability.','บทบาทชัดและการติดตามช่วยให้เกิด Accountability')],p('A policy needs visible support and resources.','นโยบายต้องมีการสนับสนุนและทรัพยากรที่เห็นจริง')))
s.append(slide('slide-05-reinforcement-and-feedback',p('Reinforce the behaviour, then learn from the friction.','เสริมพฤติกรรม แล้วเรียนรู้จากสิ่งที่ทำให้ติดขัด'),p('Use relevant reminders, safe practice and feedback to improve daily work.','ใช้ข้อความเตือนที่เกี่ยวกับงาน การฝึกที่ปลอดภัย และ Feedback เพื่อพัฒนางานประจำ'),[
[p('Remind','เตือน'),p('Explain the current risk and reporting route','อธิบายความเสี่ยงปัจจุบันและช่องทางรายงาน'),p('Use language and examples employees understand.','ใช้ภาษาและตัวอย่างที่คนเข้าใจ')],
[p('Practise','ฝึก'),p('Try a safe, authorized example','ลองตัวอย่างที่ปลอดภัยและได้รับอนุญาต'),p('Practice the response, not just spotting a spelling mistake.','ฝึกตอบสนอง ไม่ใช่แค่หาคำสะกดผิด')],
[p('Improve','ปรับปรุง'),p('Use feedback to remove obstacles','ใช้ Feedback ลดสิ่งที่ติดขัด'),p('A broken reporting button or unclear policy needs organizational action.','ปุ่มรายงานเสียหรือนโยบายไม่ชัดต้องแก้ที่องค์กร')]],
p('A learning program should reinforce safe behaviour as work and threats change. For example, explain a current impersonation risk, let staff practise using the approved reporting route and ask whether the process is easy to use. Review feedback and correct unclear instructions or inaccessible tools. Simulations should be authorized learning opportunities with constructive feedback, rather than a public ranking of people who made mistakes. Completion rates show participation, not whether a control works or people feel able to report. Look at context and practical outcomes; a rise in reports can reflect improved awareness as well as changing threat activity.','การเรียนรู้ควรเสริมพฤติกรรมปลอดภัยเมื่อการทำงานและภัยเปลี่ยน เช่น อธิบายความเสี่ยงการแอบอ้างที่พบในปัจจุบัน ให้ทีมฝึกใช้ช่องทางรายงาน แล้วถามว่าขั้นตอนใช้สะดวกหรือไม่ นำ Feedback ไปแก้คำแนะนำที่ไม่ชัดหรือเครื่องมือที่เข้าถึงไม่ได้ Simulation ควรได้รับอนุญาตและเป็นโอกาสเรียนรู้พร้อมคำแนะนำสร้างสรรค์ ไม่ใช้จัดอันดับประจานคนที่ทำพลาด อัตราเข้าเรียนแสดงการมีส่วนร่วม ไม่ได้บอกว่ามาตรการได้ผลหรือคนกล้ารายงาน ต้องดูบริบทและผลในการทำงาน จำนวนรายงานเพิ่มอาจสะท้อน Awareness ดีขึ้นหรือภัยที่เปลี่ยนก็ได้'),
[p('Use reminders appropriate to the role and current risks.','ใช้ข้อความเตือนให้เหมาะกับบทบาทและความเสี่ยง'),p('Feedback should improve the process as well as individual learning.','Feedback ควรช่วยปรับทั้งขั้นตอนและการเรียนรู้ของคน'),p('Avoid treating a single metric as proof of a secure culture.','อย่าใช้ตัวเลขเดียวพิสูจน์ว่า Culture ปลอดภัยแล้ว')],p('Learning continues after the attendance record.','การเรียนรู้ยังดำเนินต่อหลังบันทึกเข้าเรียน')))
choices=[
[p('A','A'),p('Repeat the same quiz and blame anyone who reports a mistake.','ให้ทำ Quiz เดิมซ้ำและตำหนิคนที่รายงานความผิดพลาด'),p('Blame discourages timely reporting and does not fix unclear procedures or missing support.','การกล่าวโทษทำให้ไม่กล้ารายงานเร็ว และไม่แก้ขั้นตอนไม่ชัดหรือการสนับสนุนที่ขาด')],
[p('B','B'),p('Assume annual attendance proves the culture is effective.','ถือว่าการเข้าเรียนประจำปีพิสูจน์ว่า Culture ได้ผล'),p('Attendance is participation evidence, not proof of daily behaviour or a usable reporting process.','การเข้าเรียนเป็นหลักฐานร่วมกิจกรรม ไม่ใช่ข้อพิสูจน์พฤติกรรมประจำวันหรือช่องทางรายงานที่ใช้ได้')],
[p('C','C'),p('Make reporting easy, model the policy and coach the team.','ให้รายงานง่าย ทำตามนโยบายเป็นแบบอย่าง และช่วยทีมฝึก'),p('This combines accessible reporting, leadership example, resources and relevant practice. Follow up on obstacles while keeping responsibilities clear.','รวมช่องทางรายงานที่เข้าถึงได้ แบบอย่างผู้นำ ทรัพยากร และการฝึกที่เกี่ยวข้อง พร้อมติดตามแก้สิ่งที่ติดขัดและให้หน้าที่ชัดเจน')],
[p('D','D'),p('Tell employees security belongs only to the IT team.','บอกว่า Security เป็นหน้าที่ทีม IT เท่านั้น'),p('Specialists have technical duties, but employees still need to protect information, follow policy and report concerns.','ผู้เชี่ยวชาญมีหน้าที่เทคนิค แต่พนักงานยังต้องปกป้องข้อมูล ทำตามนโยบาย และรายงานข้อกังวล')]]
s.append(slide('slide-06-culture-and-leadership-decision',p('How would you support a safer reporting culture?','จะสนับสนุน Culture การรายงานที่ปลอดภัยอย่างไร?'),p('Staff finish annual training but hesitate to report suspicious messages. Some managers bypass the policy.','ทีมเข้าเรียนประจำปีแล้ว แต่ลังเลรายงานข้อความน่าสงสัย และผู้จัดการบางคนข้ามนโยบาย'),choices,
p('This authored workplace scenario applies the source concepts rather than reproducing a review question. Employees have attended training, yet hesitate to report; management also bypasses policy. More attendance alone does not solve the observed cultural and leadership problems. A supported response makes the reporting route clear and usable, has managers model expected behaviour, provides resources and gives relevant coaching. Keep duties and follow-up clear without punishing honest prompt reports. Do not infer that every employee has sufficient awareness from attendance; ask what they understood and what prevents safe action.','สถานการณ์แต่งเพื่อฝึกนี้นำแนวคิดต้นฉบับมาใช้ ไม่ใช่โจทย์ทบทวนเดิม แม้พนักงานเข้าเรียนแล้วแต่ยังลังเลรายงาน และผู้บริหารยังข้ามนโยบาย การเพิ่มยอดเข้าเรียนอย่างเดียวไม่แก้ปัญหา Culture กับ Leadership ที่เห็น แนวทางที่มีเหตุผลคือทำช่องทางรายงานให้ชัดและใช้สะดวก ให้ผู้จัดการเป็นแบบอย่าง จัดทรัพยากรและช่วยฝึกให้เกี่ยวกับงาน ต้องให้หน้าที่และการติดตามชัดโดยไม่ลงโทษการรายงานสุจริตอย่างรวดเร็ว ทั้งนี้การเข้าเรียนไม่พิสูจน์ว่าทุกคนเข้าใจ ต้องถามว่าเรียนรู้อะไรและอะไรขวางการปฏิบัติที่ปลอดภัย'),
[p('Attendance and daily behaviour are different kinds of evidence.','การเข้าเรียนกับพฤติกรรมประจำวันเป็นหลักฐานคนละอย่าง'),p('Leadership should model expectations and fund support.','ผู้นำควรทำตามความคาดหวังและให้ทรัพยากร'),p('Reporting should reach the responsible team promptly.','รายงานควรถึงทีมรับผิดชอบโดยเร็ว')],p('Support safe actions, clear roles and honest reporting.','สนับสนุนการปฏิบัติปลอดภัย บทบาทชัด และรายงานอย่างสุจริต'),True))
l=lesson('lesson-d2-05-security-awareness-culture-leadership','2.3',p('Security Awareness, Culture & Leadership','Security Awareness, Culture และ Leadership'),p('Connect risk recognition, learning, shared daily behaviour and leadership support.','เชื่อมการรู้ทันความเสี่ยง การเรียนรู้ พฤติกรรมประจำวันร่วมกัน และการสนับสนุนจากผู้นำ'),[p('Explain the source purposes of awareness and the difference between awareness, practice and culture.','อธิบายจุดมุ่งหมาย Awareness และความต่างระหว่างการรู้ การฝึก กับ Culture'),p('Apply shared responsibility and leadership duties to a reporting scenario.','ใช้ความรับผิดชอบร่วมและหน้าที่ผู้นำกับสถานการณ์รายงานเหตุ')],s,'Actual notes§§11–13 and§24; original S21–S23; summary Awareness/Culture/Leadership; transcript awareness/culture/leadership section. Roadmap lists/Q6 attribution are stale.',[{'id':'nist-sp-800-50r1','title':'NIST SP800-50r1 — Building a Cybersecurity and Privacy Learning Program','authority':'technical-primary','url':'https://csrc.nist.gov/pubs/sp/800/50/r1/final','locator':'§2.7.1–2.7.3: ongoing awareness, constructive practice and job-related skills; supplementary clarification.'}])
publish(l);wire('security-awareness-presentations','SecurityAwareness','security-awareness');print('Authored/published six bilingual L5 slides')
